/* Fall planting reminder strip (assets/fallbar.js, written here): a slim, dismissible line under the header while a
 * town's fall planting is open. Per town: [first fall window opens, last greens/roots window closes, garlic and bulbs
 * open, garlic and bulbs close] as days of the year, from the same windows as everywhere else. */
{
  const FB = {};
  D.places.forEach(pl => {
    const ws = P.plan(D, pl).crops.flatMap(r => r.windows.filter(w => w.kind === "fall").map(w => ({ w, bulb: !!(G.crops[r.crop.id] || {}).fall })));
    if (!ws.length) return;
    const g = ws.filter(x => !x.bulb), b = ws.filter(x => x.bulb);
    FB[pl.slug] = [Math.min(...ws.map(x => x.w.start)), g.length ? Math.max(...g.map(x => x.w.end)) : 0,
      b.length ? Math.min(...b.map(x => x.w.start)) : 0, b.length ? Math.max(...b.map(x => x.w.end)) : 0];
  });
  fs.writeFileSync(path.join(ROOT, "assets/fallbar.js"), `/* Generated by scripts/build.js: fall planting reminder strip. Runs right after the header, so it never shifts the page. */
(function(){var F=${JSON.stringify(FB)};
var M=["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"],C=[0,31,59,90,120,151,181,212,243,273,304,334];
function f(n){for(var m=11;m>=0;m--)if(n>C[m])return M[m]+" "+(n-C[m]);}
var s=document.currentScript,b=(s&&s.getAttribute("data-base"))||"",d=new Date(),t=C[d.getMonth()]+d.getDate(),y=d.getFullYear(),slug="",nm="";
try{if(localStorage.getItem("rainline-fallbar")===String(y))return;slug=localStorage.getItem("rainline-place")||"";var c=(localStorage.getItem("rainline-place-name")||"").split("|");if(c[0]===slug)nm=c[1].split(",")[0];}catch(e){}
var r=F[slug],h="",sub="",ic="";
if(r&&nm){if(t>=r[0]&&t<=r[1]){h="Fall planting is open";sub="See what still goes in for "+nm;ic="lettuce";}
else if(t>=r[2]&&t<=r[3]){h="Still time for garlic and bulbs";sub="Until "+f(r[3])+" in "+nm;ic="garlic";}}
else if(!slug&&t>=182&&t<=319){h="It's fall planting season";sub="See what still goes in for your town";ic=t>=274?"garlic":"lettuce";}
if(!h)return;
document.write('<div class="fall-bar" role="region" aria-label="Fall planting reminder"><div class="wrap"><a class="fb-main" href="'+b+'fall-planting/"><img class="fb-ico" src="'+b+'assets/img/crops/'+ic+'.webp" width="36" height="36" alt="" aria-hidden="true"><span class="fb-t"><strong>'+h+'</strong><span>'+sub+'</span></span><span class="fb-go">See list \\u203a</span></a><button type="button" aria-label="Hide this reminder">\\u00d7</button></div></div>');
var el=s&&s.nextElementSibling;if(el&&/fall-bar/.test(el.className))el.querySelector("button").onclick=function(){el.remove();try{localStorage.setItem("rainline-fallbar",String(y));}catch(e){}};
})();
`);
}
